export interface OwnedPostcssConfig {
  readonly plugins: Readonly<Record<string, Readonly<Record<string, never>>>>;
}

const config: OwnedPostcssConfig = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

import { defineConfig } from "vitest/config";

const root = ".";

export default defineConfig({
  root,
  test: {
    include: ["../class-name-composition/component.test.ts"],
  },
});

export interface UiRef<Value> {
  current: Value;
}

export function mountUiRoot(container: Element): void {
  const root = container;
  if (root) {
    root.textContent = "mounted";
  }
}
